// Disk is authoritative across browsers; localStorage remains an emergency cache.
const browserSave=save,browserRender=render;
let diskIdentity='',diskReady=false,diskRevision=0,diskTimer,diskBusy=false,diskAgain=false,diskConflict=false,lastDiskData='';
const savedLabel=()=>document.querySelector('#saved');
function showDiskError(message){let banner=document.querySelector('#diskSaveWarning');if(!banner){banner=document.createElement('div');banner.id='diskSaveWarning';banner.className='notice';banner.style.cssText='border-color:#9c6959;color:#f1c6b1';document.querySelector('.notice').after(banner)}banner.textContent=message;}
async function flushDisk(){clearTimeout(diskTimer);if(!diskReady||diskConflict||data.deleted)return;if(diskBusy){diskAgain=true;return}const snapshot=JSON.stringify(data);if(snapshot===lastDiskData){savedLabel().textContent='● 已保存到本机';return}diskBusy=true;const identity=String(data.project_id||data.local_id||data.title||'unnamed');if(identity!==diskIdentity){try{const existing=await(await fetch('/api/project?id='+encodeURIComponent(identity))).json();diskRevision=existing.revision;diskIdentity=identity;}catch(e){diskBusy=false;throw e}}savedLabel().textContent='● 正在保存到本机…';try{const r=await fetch('/api/project',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:diskRevision,project:JSON.parse(snapshot)})});const result=await r.json();if(!r.ok){if(r.status===409)diskConflict=true;throw Error(result.error||'无法保存到本机')}diskRevision=result.revision;lastDiskData=snapshot;savedLabel().textContent='● 已保存到本机';document.querySelector('#diskSaveWarning')?.remove();}catch(e){savedLabel().textContent='● 仅有浏览器备份';showDiskError(e.message+' 当前浏览器中仍保留备份，可导出 JSON。');}finally{diskBusy=false;if(diskAgain){diskAgain=false;scheduleDisk()}}}
function scheduleDisk(){if(!diskReady||diskConflict||data.deleted)return;clearTimeout(diskTimer);if(JSON.stringify(data)!==lastDiskData){savedLabel().textContent='● 等待保存到本机…';diskTimer=setTimeout(flushDisk,500)}else savedLabel().textContent='● 已保存到本机';}
save=function(){browserSave();scheduleDisk()};render=function(){browserRender();scheduleDisk()};document.querySelector('#save').onclick=async()=>{browserSave();await flushDisk();if(!diskConflict&&lastDiskData===JSON.stringify(data))toast('已保存到本机，其他浏览器可读取')};
async function loadDiskProject(){savedLabel().textContent='● 正在读取本机项目…';try{const cached=clone(data),cachedIdentity=String(cached.project_id||cached.local_id||cached.title||'unnamed');let r=await fetch('/api/project?id='+encodeURIComponent(cachedIdentity));if(!r.ok)throw Error('本地项目服务未就绪');let result=await r.json();if(result.project?.deleted||result.purged_at){result=await(await fetch('/api/project')).json();if(!result.project){data={title:'未创建项目',synopsis:'导入 JSON 开始新项目，或从回收站恢复。',genre:'',style:'',ratio:'',episodes:0,duration:0,characters:[],shots:[],stages:{},deleted:true};diskReady=true;diskRevision=0;diskIdentity='';lastDiskData=JSON.stringify(data);browserSave();render();return;}}if(!result.project){if((cached.project_id||cached.local_id)&&!cached.deleted){const created=await fetch('/api/project',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:0,project:cached})});if(!created.ok)throw Error('浏览器中的新项目已保留，请重试保存');r=await fetch('/api/project?id='+encodeURIComponent(cachedIdentity));result=await r.json();}else{r=await fetch('/api/project');result=await r.json();}}diskRevision=result.revision;diskIdentity=result.project?String(result.project.project_id||result.project.local_id||result.project.title||'unnamed'):cachedIdentity;if(result.project){const local=JSON.stringify(data),remote=JSON.stringify(result.project);if(local!==remote&&data.project_id&&data.title!==sample.title){localStorage.setItem('frame-studio-pre-disk-backup',local);}data=result.project;ci=si=tab=0;lastDiskData=remote;browserSave();diskReady=true;render();}else{diskReady=true;if(data.project_id||data.title!==sample.title){data.local_id??=crypto.randomUUID();await flushDisk()}else{savedLabel().textContent='● 示例项目 · 尚未保存到本机';}}const note=document.createElement('p');note.className='subtle';note.textContent='项目自动保存到 D:\\AIPlatform\\Output\\DramaStudio\\Projects，同一台电脑不同浏览器均可读取。';document.querySelector('.overview').append(note);}catch(e){savedLabel().textContent='● 仅有浏览器备份';showDiskError(e.message+'，现有浏览器数据保留，请稍后刷新。');}}
loadDiskProject();

let checkingUpscaleUpdates=false;
setInterval(async()=>{if(checkingUpscaleUpdates||!diskReady||diskBusy||diskConflict||data.deleted||JSON.stringify(data)!==lastDiskData)return;checkingUpscaleUpdates=true;const id=diskIdentity;try{const r=await fetch('/api/project?id='+encodeURIComponent(id)),remote=await r.json();if(id!==diskIdentity||diskBusy||diskConflict||JSON.stringify(data)!==lastDiskData)return;if(remote.revision>diskRevision&&remote.project&&!document.querySelector('dialog[open]')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){data=remote.project;diskRevision=remote.revision;lastDiskData=JSON.stringify(data);browserSave();diskDeferredRender=true;renderDiskUpdatesWhenIdle();}}catch{}finally{checkingUpscaleUpdates=false;}},2500);

let diskDeferredRender=false;
function renderDiskUpdatesWhenIdle(){if(!diskDeferredRender)return;if([...document.querySelectorAll("video")].some(v=>!v.paused&&!v.ended))return;diskDeferredRender=false;const x=window.scrollX,y=window.scrollY;render();requestAnimationFrame(()=>window.scrollTo(x,y));}
document.addEventListener("pause",renderDiskUpdatesWhenIdle,true);document.addEventListener("ended",renderDiskUpdatesWhenIdle,true);
